/**
 * MESCO Trust CMS — Frontend Audit (Playwright)
 *
 * Usage:
 *   node scripts/frontend-audit.js [baseUrl]
 *   node scripts/frontend-audit.js https://mesco-demo.aiolos.cloud
 *
 * Outputs:
 *   playwright-artifacts/frontend-audit/results.json
 *   playwright-artifacts/frontend-audit/screenshots/*.png
 *   docs/FRONTEND_AUDIT_REPORT.md   (generated by a second pass / manually)
 */

const fs = require("fs");
const path = require("path");
const { chromium } = require("@playwright/test");

const TARGET = (process.argv[2] || "https://mesco-demo.aiolos.cloud").replace(/\/$/, "");
const OUT_DIR = path.join(process.cwd(), "playwright-artifacts", "frontend-audit");
const SHOT_DIR = path.join(OUT_DIR, "screenshots");

const USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0 Safari/537.36 MESCO-Audit";

/* ─────────────────────────── helpers ─────────────────────────── */

function slugify(url) {
  const p = new URL(url).pathname.replace(/^\//, "").replace(/\/$/, "");
  return (p.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "") || "home").toLowerCase();
}

function writeJson(file, data) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(data, null, 2), "utf8");
}

function push(arr, value) {
  if (value) arr.push(value);
}

/* ───────────────────────── page audit ───────────────────────── */

async function auditPage(context, url) {
  const page = await context.newPage();

  const consoleErrors = [];
  const pageErrors = [];
  const failedRequests = [];
  const badResponses = [];

  page.on("console", (msg) => {
    if (msg.type() === "error") {
      const t = msg.text() || "";
      if (/favicon/i.test(t)) return;
      consoleErrors.push(t.slice(0, 300));
    }
  });
  page.on("pageerror", (err) => pageErrors.push(String(err.message || err).slice(0, 300)));
  page.on("requestfailed", (req) => {
    const f = req.failure();
    failedRequests.push({
      url: req.url().slice(0, 250),
      reason: (f && f.errorText) || "unknown",
      type: req.resourceType(),
    });
  });
  page.on("response", (res) => {
    const s = res.status();
    if (s >= 400) badResponses.push({ url: res.url().slice(0, 250), status: s });
  });

  const result = {
    url,
    status: null,
    ok: false,
    loadMs: null,
    title: "",
    titleLength: 0,
    metaDescription: "",
    metaDescriptionLength: 0,
    canonical: "",
    robotsMeta: "",
    og: {},
    twitter: {},
    jsonLd: { count: 0, types: [] },
    hreflang: [],
    htmlLang: "",
    hasViewport: false,
    viewportContent: "",
    favicon: "",
    headings: { h1: [], h2: 0, h3: 0, h4: 0, orderIssues: [] },
    images: { total: 0, broken: [], missingAlt: [], noDimensions: 0, largeFiles: [] },
    links: { internal: [], external: [], emptyHref: [], missingRel: [], javascriptHref: [] },
    forms: { count: 0, unlabelled: 0, withoutAction: 0 },
    a11y: { unnamedButtons: 0, unnamedLinks: 0, inputsWithoutLabel: 0, positiveTabindex: 0 },
    perf: { transferBytes: 0, requestCount: 0, domNodes: 0, scripts: 0, stylesheets: 0, images: 0, fonts: 0 },
    errors: { consoleErrors, pageErrors, failedRequests, badResponses },
    issues: [],
  };

  let res;
  const started = Date.now();
  try {
    res = await page.goto(url, { waitUntil: "domcontentloaded", timeout: 60_000 });
  } catch (err) {
    result.status = 0;
    result.issues.push({ sev: "critical", cat: "load", msg: `Navigation failed: ${err.message}` });
    await page.close();
    return result;
  }

  result.status = res ? res.status() : 0;
  result.ok = result.status >= 200 && result.status < 400;

  // let lazy content settle
  try {
    await page.waitForLoadState("networkidle", { timeout: 25_000 });
  } catch {
    /* ignore — long-polling / animations */
  }
  await page.evaluate(() => {
    window.scrollTo(0, document.body.scrollHeight);
    window.scrollTo(0, 0);
  });
  await page.waitForTimeout(1200);

  result.loadMs = Date.now() - started;

  /* ---------- in-page analysis ---------- */
  const data = await page.evaluate(() => {
    const abs = (h) => {
      try {
        return new URL(h, document.baseURI).href;
      } catch {
        return "";
      }
    };
    const txt = (el) => (el.textContent || "").replace(/\s+/g, " ").trim();

    const titleEl = document.querySelector("title");
    const title = titleEl ? document.title.trim() : "";
    const descEl = document.querySelector('meta[name="description"]');
    const desc = descEl ? (descEl.getAttribute("content") || "").trim() : "";
    const canonEl = document.querySelector('link[rel="canonical"]');
    const robotsEl = document.querySelector('meta[name="robots"]');
    const viewportEl = document.querySelector('meta[name="viewport"]');
    const iconEl = document.querySelector('link[rel~="icon"], link[rel="shortcut icon"], link[rel="apple-touch-icon"]');

    const og = {};
    document.querySelectorAll('meta[property^="og:"]').forEach((m) => {
      og[m.getAttribute("property")] = (m.getAttribute("content") || "").trim();
    });
    const twitter = {};
    document.querySelectorAll('meta[name^="twitter:"]').forEach((m) => {
      twitter[m.getAttribute("name")] = (m.getAttribute("content") || "").trim();
    });

    let jsonLdCount = 0;
    const jsonLdTypes = [];
    document.querySelectorAll('script[type="application/ld+json"]').forEach((s) => {
      jsonLdCount += 1;
      try {
        const parsed = JSON.parse(s.textContent || "{}");
        const walk = (o) => {
          if (!o || typeof o !== "object") return;
          if (Array.isArray(o)) return o.forEach(walk);
          if (o["@type"]) jsonLdTypes.push(String(o["@type"]));
          Object.values(o).forEach(walk);
        };
        walk(parsed);
      } catch {
        jsonLdTypes.push("INVALID_JSON");
      }
    });

    /* headings */
    const hs = Array.from(document.querySelectorAll("h1,h2,h3,h4,h5,h6"));
    const headingList = hs.map((h) => ({ tag: h.tagName.toLowerCase(), text: txt(h).slice(0, 90) }));
    const orderIssues = [];
    let prev = 0;
    hs.forEach((h) => {
      const lvl = Number(h.tagName[1]);
      if (prev && lvl > prev + 1) orderIssues.push(`h${prev} → h${lvl} ("${txt(h).slice(0, 40)}")`);
      prev = lvl;
    });

    /* images */
    const imgs = Array.from(document.images);
    const images = {
      total: imgs.length,
      broken: [],
      missingAlt: [],
      noDimensions: 0,
      largeFiles: [],
    };
    imgs.forEach((im) => {
      const src = im.currentSrc || im.src || "";
      if (im.complete && im.naturalWidth === 0) {
        images.broken.push({ src: src.slice(0, 250), alt: im.getAttribute("alt") || "" });
      }
      const alt = im.getAttribute("alt");
      if (alt === null) images.missingAlt.push(src.slice(0, 200));
      if (!im.getAttribute("width") || !im.getAttribute("height")) images.noDimensions += 1;
      if (src) images.largeFiles.push(src);
    });

    /* links */
    const links = { internal: [], external: [], emptyHref: [], missingRel: [], javascriptHref: [] };
    const seenInternal = new Set();
    document.querySelectorAll("a").forEach((a) => {
      const href = a.getAttribute("href");
      if (href === null || href.trim() === "") {
        links.emptyHref.push(txt(a).slice(0, 60));
        return;
      }
      if (/^javascript:/i.test(href)) {
        links.javascriptHref.push(href.slice(0, 120));
        return;
      }
      const full = abs(href);
      if (!full) return;
      let u;
      try {
        u = new URL(full);
      } catch {
        return;
      }
      if (u.origin === window.location.origin) {
        if (!seenInternal.has(u.pathname + u.search)) {
          seenInternal.add(u.pathname + u.search);
          links.internal.push(full);
        }
        if (u.origin !== window.location.origin && !a.getAttribute("rel")) {
          // unreachable, kept for clarity
        }
      } else {
        const isMailtoTel =
          u.protocol === "mailto:" || u.protocol === "tel:" || u.protocol === "javascript:";
        if (!isMailtoTel && !a.getAttribute("rel")) links.missingRel.push(full.slice(0, 200));
        if (!isMailtoTel) links.external.push(full);
      }
    });

    /* forms + labels */
    const forms = { count: 0, unlabelled: 0, withoutAction: 0 };
    document.querySelectorAll("form").forEach((f) => {
      forms.count += 1;
      if (!f.getAttribute("action")) forms.withoutAction += 1;
    });
    let unlabelled = 0;
    document.querySelectorAll("input, select, textarea").forEach((el) => {
      const t = (el.getAttribute("type") || "text").toLowerCase();
      if (t === "hidden" || t === "submit" || t === "button") return;
      const id = el.getAttribute("id");
      const hasLabel = (id && document.querySelector(`label[for="${CSS.escape(id)}"]`)) ||
        el.closest("label") !== null ||
        !!el.getAttribute("aria-label") ||
        !!el.getAttribute("aria-labelledby") ||
        !!el.getAttribute("title");
      if (!hasLabel) unlabelled += 1;
    });

    /* accessible names */
    let unnamedButtons = 0;
    document.querySelectorAll("button").forEach((b) => {
      const name = (b.textContent || "").trim() || b.getAttribute("aria-label") || b.getAttribute("title");
      if (!name) unnamedButtons += 1;
    });
    let unnamedLinks = 0;
    document.querySelectorAll("a").forEach((a) => {
      const name = (a.textContent || "").trim() || a.getAttribute("aria-label") || a.getAttribute("title") ||
        a.querySelector("img[alt]")?.getAttribute("alt");
      if (!name) unnamedLinks += 1;
    });
    let positiveTabindex = 0;
    document.querySelectorAll("[tabindex]").forEach((el) => {
      const v = Number(el.getAttribute("tabindex"));
      if (Number.isFinite(v) && v > 0) positiveTabindex += 1;
    });

    /* perf */
    const perf = {
      transferBytes: 0,
      requestCount: 0,
      domNodes: document.querySelectorAll("*").length,
      scripts: document.querySelectorAll("script[src]").length,
      stylesheets: document.querySelectorAll('link[rel="stylesheet"]').length,
      images: imgs.length,
      fonts: 0,
    };
    try {
      const res = performance.getEntriesByType("resource");
      perf.requestCount = res.length;
      perf.transferBytes = res.reduce((a, r) => a + (r.transferSize || 0), 0);
      perf.fonts = res.filter((r) => r.initiatorType === "css" || /\.woff2?|\.ttf|\.otf/i.test(r.name)).length;
    } catch {}

    return {
      title,
      desc,
      canonical: canonEl ? (canonEl.getAttribute("href") || "").trim() : "",
      robotsMeta: robotsEl ? (robotsEl.getAttribute("content") || "").trim() : "",
      viewport: viewportEl ? (viewportEl.getAttribute("content") || "").trim() : "",
      icon: iconEl ? (iconEl.getAttribute("href") || "").trim() : "",
      og,
      twitter,
      jsonLdCount,
      jsonLdTypes,
      hreflang: Array.from(document.querySelectorAll('link[rel="alternate"][hreflang]')).map((l) => l.getAttribute("hreflang")),
      htmlLang: document.documentElement.getAttribute("lang") || "",
      headings: headingList,
      headingOrderIssues: orderIssues,
      images,
      links,
      forms,
      a11y: { unnamedButtons, unnamedLinks, inputsWithoutLabel: unlabelled, positiveTabindex },
      perf,
    };
  });

  /* ---------- map into result ---------- */
  result.title = data.title;
  result.titleLength = data.title.length;
  result.metaDescription = data.desc;
  result.metaDescriptionLength = data.desc.length;
  result.canonical = data.canonical;
  result.robotsMeta = data.robotsMeta;
  result.viewportContent = data.viewport;
  result.hasViewport = !!data.viewport;
  result.favicon = data.icon;
  result.og = data.og;
  result.twitter = data.twitter;
  result.jsonLd = { count: data.jsonLdCount, types: Array.from(new Set(data.jsonLdTypes)) };
  result.hreflang = data.hreflang;
  result.htmlLang = data.htmlLang;
  result.headings = {
    h1: data.headings.filter((h) => h.tag === "h1").map((h) => h.text),
    h2: data.headings.filter((h) => h.tag === "h2").length,
    h3: data.headings.filter((h) => h.tag === "h3").length,
    h4: data.headings.filter((h) => h.tag === "h4").length,
    orderIssues: data.headingOrderIssues,
  };
  result.images = data.images;
  result.links = data.links;
  result.forms = data.forms;
  result.a11y = data.a11y;
  result.perf = data.perf;

  /* screenshot */
  try {
    await page.screenshot({ path: path.join(SHOT_DIR, `${slugify(url)}.png`), fullPage: false });
  } catch {}

  await page.close();
  return result;
}

/* ───────────────────────── issue builder ───────────────────────── */

function buildIssues(r) {
  const issues = [];
  const add = (sev, cat, msg) => issues.push({ sev, cat, msg });

  if (!r.ok) add("critical", "http", `HTTP ${r.status}`);
  if (!r.title) add("critical", "seo", "Missing <title>");
  else {
    if (r.titleLength < 15) add("major", "seo", `Title too short (${r.titleLength} chars): "${r.title}"`);
    if (r.titleLength > 65) add("minor", "seo", `Title too long (${r.titleLength} chars) — will truncate in Google`);
  }
  if (!r.metaDescription) add("major", "seo", "Missing meta description");
  else if (r.metaDescriptionLength < 60) add("minor", "seo", `Meta description short (${r.metaDescriptionLength} chars)`);
  else if (r.metaDescriptionLength > 175) add("minor", "seo", `Meta description long (${r.metaDescriptionLength} chars) — will truncate`);
  if (!r.canonical) add("major", "seo", "Missing canonical URL");
  else if (/localhost|127\.0\.0\.1/.test(r.canonical)) add("critical", "seo", `Canonical points to localhost: ${r.canonical}`);

  if (r.headings.h1.length === 0) add("critical", "seo", "No <h1> on page");
  if (r.headings.h1.length > 1) add("major", "seo", `${r.headings.h1.length} <h1> tags — should be exactly 1`);
  if (r.headings.orderIssues.length) add("minor", "a11y", `Heading order skip: ${r.headings.orderIssues.join(" | ")}`);

  if (!r.og["og:title"]) add("major", "seo", "Missing og:title");
  if (!r.og["og:description"]) add("major", "seo", "Missing og:description");
  if (!r.og["og:image"]) add("major", "social", "Missing og:image — link previews will be blank");
  else if (/localhost/.test(r.og["og:image"])) add("critical", "social", `og:image points to localhost: ${r.og["og:image"]}`);
  if (!r.og["og:url"]) add("minor", "social", "Missing og:url");
  if (!r.twitter["twitter:card"]) add("minor", "social", "Missing twitter:card");

  if (!r.hasViewport) add("critical", "mobile", "Missing viewport meta — page will not be responsive");
  if (!r.htmlLang) add("major", "a11y", "<html> has no lang attribute");
  if (!r.favicon) add("minor", "seo", "No favicon link");

  if (r.jsonLd.count === 0) add("minor", "seo", "No JSON-LD structured data");

  if (r.images.broken.length) add("critical", "images", `${r.images.broken.length} broken image(s): ${r.images.broken.slice(0, 3).map((b) => b.src).join(", ")}`);
  if (r.images.missingAlt.length) add("major", "a11y", `${r.images.missingAlt.length} image(s) missing alt attribute`);
  if (r.images.total > 0 && r.images.noDimensions / r.images.total > 0.5)
    add("minor", "perf", `${r.images.noDimensions}/${r.images.total} images without width/height — causes CLS`);

  if (r.links.emptyHref.length) add("major", "links", `${r.links.emptyHref.length} anchor(s) with empty href: "${r.links.emptyHref.slice(0, 3).join('", "')}"`);
  if (r.links.javascriptHref.length) add("minor", "a11y", `${r.links.javascriptHref.length} javascript: link(s) — not crawlable`);
  if (r.links.missingRel.length) add("minor", "seo", `${r.links.missingRel.length} external link(s) without rel="noopener"`);

  if (r.a11y.unnamedButtons) add("major", "a11y", `${r.a11y.unnamedButtons} button(s) without accessible name`);
  if (r.a11y.unnamedLinks) add("major", "a11y", `${r.a11y.unnamedLinks} link(s) without accessible name`);
  if (r.a11y.inputsWithoutLabel) add("critical", "a11y", `${r.a11y.inputsWithoutLabel} form field(s) without label`);
  if (r.a11y.positiveTabindex) add("minor", "a11y", `${r.a11y.positiveTabindex} positive tabindex (breaks tab order)`);

  if (r.errors.pageErrors.length) add("critical", "js", `${r.errors.pageErrors.length} uncaught JS error(s): ${r.errors.pageErrors[0]}`);
  if (r.errors.consoleErrors.length) add("major", "js", `${r.errors.consoleErrors.length} console error(s): ${r.errors.consoleErrors[0]}`);
  const asset404 = r.errors.badResponses.filter((b) => !/\/api\/|\/admin/.test(b.url));
  if (asset404.length) add("major", "assets", `${asset404.length} asset request(s) returned 4xx/5xx: ${asset404.slice(0, 2).map((a) => a.url).join(", ")}`);

  const mb = r.perf.transferBytes / 1048576;
  if (mb > 5) add("major", "perf", `Heavy page weight: ${mb.toFixed(2)} MB`);
  else if (mb > 3) add("minor", "perf", `Page weight ${mb.toFixed(2)} MB`);
  if (r.loadMs > 6000) add("major", "perf", `Slow load: ${(r.loadMs / 1000).toFixed(1)}s`);
  if (r.perf.domNodes > 4000) add("minor", "perf", `Heavy DOM: ${r.perf.domNodes} nodes`);

  return issues;
}

/* ───────────────────────── discovery ───────────────────────── */

async function discoverPages(context) {
  const found = new Map();
  const TARGET_URL = new URL(TARGET);
  const TARGET_ORIGIN = TARGET_URL.origin;

  /**
   * Normalise any URL onto the audited origin.
   * Sitemap entries are hardcoded to http://localhost:3000 in this project,
   * so localhost/127.0.0.1 hosts are rewritten to the audited host.
   */
  const pushUrl = (u) => {
    try {
      const url = new URL(u, TARGET);
      if (url.hostname === "localhost" || url.hostname === "127.0.0.1") {
        url.protocol = TARGET_URL.protocol;
        url.host = TARGET_URL.host;
      }
      if (url.origin !== TARGET_ORIGIN) return;
      if (/^\/(admin|api|preview|component-check|_next)/.test(url.pathname)) return;
      url.hash = "";
      const key = url.origin + url.pathname;
      if (!found.has(key)) found.set(key, url.origin + url.pathname);
    } catch (e) {
      console.log("  ! bad url skipped:", String(u).slice(0, 100));
    }
  };

  pushUrl(TARGET + "/");

  // sitemap
  try {
    const r = await context.request.get(TARGET + "/sitemap.xml", { timeout: 30000 });
    const xml = await r.text();
    const locs = xml.match(/<loc>([^<]+)<\/loc>/g) || [];
    locs.forEach((l) => pushUrl(l.replace(/<\/?loc>/g, "").trim()));
    console.log(`  sitemap: ${locs.length} <loc> entries`);
  } catch (e) {
    console.log("  ! sitemap fetch failed:", e.message);
  }

  // nav crawl from home (up to 2 levels deep)
  const page = await context.newPage();
  const queue = [TARGET + "/"];
  const visited = new Set();
  for (let depth = 0; depth < 2 && queue.length && visited.size < 80; depth += 1) {
    const next = [];
    for (const u of queue) {
      if (visited.has(u)) continue;
      visited.add(u);
      try {
        await page.goto(u, { waitUntil: "domcontentloaded", timeout: 45000 });
        const hrefs = await page.evaluate(() =>
          Array.from(document.querySelectorAll("a[href]"))
            .map((a) => a.getAttribute("href"))
            .filter(Boolean)
        );
        for (const h of hrefs) {
          try {
            const abs = new URL(h, TARGET).toString();
            const url = new URL(abs);
            if (url.origin !== TARGET_ORIGIN) continue;
            if (/^\/(admin|api|preview|component-check|_next)/.test(url.pathname)) continue;
            const key = url.origin + url.pathname;
            pushUrl(abs);
            if (!visited.has(key) && !next.includes(key)) next.push(key);
          } catch {}
        }
      } catch (e) {
        console.log(`  ! crawl failed ${u.replace(TARGET, "") || "/"}: ${e.message.slice(0, 70)}`);
      }
    }
    queue.splice(0, queue.length, ...next);
  }
  await page.close();

  console.log(`  discovered ${found.size} pages`);
  return Array.from(found.values());
}

/* ───────────────────────── special checks ───────────────────────── */

async function checkSpecials(context) {
  const out = {};

  // robots.txt
  try {
    const r = await context.request.get(TARGET + "/robots.txt", { timeout: 20000 });
    out.robots = { status: r.status(), body: (await r.text()).slice(0, 1200) };
  } catch (e) {
    out.robots = { status: 0, body: "", error: e.message };
  }

  // sitemap
  try {
    const r = await context.request.get(TARGET + "/sitemap.xml", { timeout: 20000 });
    const body = await r.text();
    const locs = (body.match(/<loc>([^<]+)<\/loc>/g) || []).map((l) => l.replace(/<\/?loc>/g, "").trim());
    out.sitemap = {
      status: r.status(),
      urlCount: locs.length,
      localhostUrls: locs.filter((u) => /localhost|127\.0\.0\.1/.test(u)).length,
      sample: locs.slice(0, 5),
    };
  } catch (e) {
    out.sitemap = { status: 0, error: e.message };
  }

  // 404 page
  const p404 = await context.newPage();
  try {
    const res = await p404.goto(TARGET + "/this-page-definitely-does-not-exist-audit", {
      waitUntil: "domcontentloaded",
      timeout: 40000,
    });
    out.notFound = { status: res ? res.status() : 0, hasHeading: await p404.locator("h1").count() > 0 };
  } catch (e) {
    out.notFound = { status: 0, error: e.message };
  }
  await p404.close();

  // http -> https redirect
  try {
    const httpUrl = TARGET.replace(/^https:/, "http:");
    const r = await context.request.get(httpUrl + "/", { maxRedirects: 0, timeout: 20000 });
    out.httpRedirect = { status: r.status(), location: r.headers()["location"] || null };
  } catch (e) {
    out.httpRedirect = { status: 0, error: e.message, note: "connection refused or no redirect" };
  }

  // security headers
  try {
    const r = await context.request.get(TARGET + "/", { timeout: 20000 });
    const h = r.headers();
    out.securityHeaders = {
      "strict-transport-security": h["strict-transport-security"] || null,
      "content-security-policy": h["content-security-policy"] || null,
      "x-content-type-options": h["x-content-type-options"] || null,
      "x-frame-options": h["x-frame-options"] || null,
      "referrer-policy": h["referrer-policy"] || null,
      "permissions-policy": h["permissions-policy"] || null,
    };
  } catch {}

  return out;
}

/* ───────────────────────── link check ───────────────────────── */

async function checkInternalLinks(context, pages, results) {
  const all = new Set();
  results.forEach((r) => (r.links.internal || []).forEach((l) => all.add(l)));
  const list = Array.from(all).slice(0, 220);
  const broken = [];
  const listPage = await context.newPage();

  for (const u of list) {
    try {
      const res = await listPage.goto(u, { waitUntil: "domcontentloaded", timeout: 35000 });
      const s = res ? res.status() : 0;
      if (s >= 400) broken.push({ url: u, status: s });
    } catch (e) {
      broken.push({ url: u, status: 0, error: e.message.slice(0, 120) });
    }
  }
  await listPage.close();
  return { checked: list.length, broken };
}

/* ───────────────────────── main ───────────────────────── */

(async () => {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  console.log(`\n▶ MESCO Frontend Audit → ${TARGET}\n`);

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    userAgent: USER_AGENT,
    ignoreHTTPSErrors: true,
    reducedMotion: "reduce",
  });

  console.log("· discovering pages…");
  const urls = await discoverPages(context);
  console.log(`  found ${urls.length} pages\n`);

  const results = [];
  for (let i = 0; i < urls.length; i += 1) {
    const u = urls[i];
    process.stdout.write(`  [${i + 1}/${urls.length}] ${u.replace(TARGET, "") || "/"} `);
    const r = await auditPage(context, u);
    r.issues = buildIssues(r);
    results.push(r);
    const crit = r.issues.filter((x) => x.sev === "critical").length;
    const maj = r.issues.filter((x) => x.sev === "major").length;
    const min = r.issues.filter((x) => x.sev === "minor").length;
    console.log(`→ ${r.status} | C:${crit} M:${maj} m:${min}`);
  }

  console.log("\n· special checks (robots / sitemap / 404 / https / headers)…");
  const specials = await checkSpecials(context);

  console.log("· internal link check…");
  const linkCheck = await checkInternalLinks(context, urls, results);

  /* mobile pass on 4 key pages */
  console.log("· mobile pass…");
  const mobileCtx = await browser.newContext({
    viewport: { width: 375, height: 812 },
    isMobile: true,
    hasTouch: true,
    userAgent: USER_AGENT,
    ignoreHTTPSErrors: true,
    deviceScaleFactor: 2,
  });
  const mobilePages = ["/", "/donate-now", "/get-involved/contact-us", "/blog"].filter(Boolean);
  const mobile = [];
  for (const p of mobilePages) {
    const u = TARGET + p;
    const page = await mobileCtx.newPage();
    const errs = [];
    page.on("pageerror", (e) => errs.push(String(e.message).slice(0, 200)));
    try {
      const res = await page.goto(u, { waitUntil: "networkidle", timeout: 50000 });
      const overflow = await page.evaluate(() => ({
        scrollW: document.documentElement.scrollWidth,
        clientW: document.documentElement.clientWidth,
      }));
      await page.screenshot({ path: path.join(SHOT_DIR, `mobile-${slugify(u)}.png`), fullPage: false });
      mobile.push({
        url: u,
        status: res ? res.status() : 0,
        horizontalOverflow: overflow.scrollW - overflow.clientW > 4 ? overflow.scrollW - overflow.clientW : 0,
        errors: errs,
      });
      console.log(`  mobile ${p} → ${res ? res.status() : 0} overflow:${overflow.scrollW - overflow.clientW}`);
    } catch (e) {
      mobile.push({ url: u, status: 0, error: e.message.slice(0, 150) });
    }
    await page.close();
  }
  await mobileCtx.close();

  const report = {
    generatedAt: new Date().toISOString(),
    target: TARGET,
    pageCount: results.length,
    specials,
    linkCheck,
    mobile,
    pages: results.map((r) => ({
      url: r.url,
      status: r.status,
      loadMs: r.loadMs,
      title: r.title,
      titleLength: r.titleLength,
      metaDescriptionLength: r.metaDescriptionLength,
      canonical: r.canonical,
      h1Count: r.headings.h1.length,
      jsonLd: r.jsonLd.types,
      images: { total: r.images.total, broken: r.images.broken.length, missingAlt: r.images.missingAlt.length },
      internalLinks: r.links.internal.length,
      weightMB: Number((r.perf.transferBytes / 1048576).toFixed(2)),
      domNodes: r.perf.domNodes,
      consoleErrors: r.errors.consoleErrors.length,
      pageErrors: r.errors.pageErrors.length,
      issueCount: r.issues.length,
      issues: r.issues,
      detail: r,
    })),
  };

  writeJson(path.join(OUT_DIR, "results.json"), report);

  /* console summary */
  const allIssues = results.flatMap((r) => r.issues.map((i) => ({ ...i, url: r.url })));
  const bySev = (s) => allIssues.filter((i) => i.sev === s);
  console.log(`\n═══ SUMMARY ═══`);
  console.log(`Pages audited : ${results.length}`);
  console.log(`Critical      : ${bySev("critical").length}`);
  console.log(`Major         : ${bySev("major").length}`);
  console.log(`Minor         : ${bySev("minor").length}`);
  console.log(`Broken links  : ${linkCheck.broken.length} / ${linkCheck.checked}`);
  console.log(`JSON written  : ${path.join(OUT_DIR, "results.json")}`);

  await browser.close();
})().catch((e) => {
  console.error("FATAL:", e);
  process.exit(1);
});
